            var ds = state.domainState;

            var revenue = 0;
            var costs = 45.0;
            var profit = 0;
            var ipGain = 0;
            var subscribersGained = 0;
            var hitRate = ds.hitRate;
            var catalogRevenue = 12.0;
            var otherRevenue = 3.0;
            var contentRevenue = 0;
            var ancillaryRevenue = 0;
            var platformRevenue = 0;
            var partnershipBonus = 0;
            var franchiseRevenue = 0;
            var extraCosts = 0;

            if (period === 1) {
                var sp = this.STRATEGY_PARAMS[d.productionStrategy] || this.STRATEGY_PARAMS['hybrid'];
                var numProjects = sp.numProjects;
                var baseHR = sp.baseHitRate;
                var revPerHit = sp.revenuePerHit;
                var ipPerHit = sp.ipPerHit;

                var hitAdj = 0;
                hitAdj += (d.realityAlloc - 20) * 0.002;

                var activeGenres = 0;
                if (d.dramaAlloc > 5) activeGenres++;
                if (d.realityAlloc > 5) activeGenres++;
                if (d.docAnimAlloc > 5) activeGenres++;
                if (d.filmAlloc > 5) activeGenres++;
                if (d.spinoffAlloc > 5) activeGenres++;
                if (activeGenres >= 4) hitAdj += 0.03;

                var revAdj = (d.dramaAlloc - 25) * 0.08;

                if (d.releaseStrategy === 'weekly') {
                    hitAdj += 0.05;
                } else if (d.releaseStrategy === 'binge') {
                    revAdj += 0.8;
                } else if (d.releaseStrategy === 'split') {
                    hitAdj += 0.025;
                    revAdj += 0.4;
                }

                hitRate = Math.max(0.20, Math.min(0.85, baseHR + hitAdj));
                var hits = Math.round(numProjects * hitRate);
                var misses = numProjects - hits;
                var finalRevPerHit = Math.max(1.5, revPerHit + revAdj);

                contentRevenue = hits * finalRevPerHit + misses * 0.8;
                ipGain = hits * ipPerHit;

                revenue = contentRevenue + catalogRevenue + otherRevenue;
                profit = revenue - costs;

                ds.hitRate = hitRate;
                ds.numHits = hits;
                ds.numProjects = numProjects;
                ds.lastContentRevenue = contentRevenue;

            } else if (period === 2) {
                var platP = this.PLATFORM_PARAMS[d.platformStrategy] || this.PLATFORM_PARAMS['hybrid_plat'];
                var partP = this.PARTNER_PARAMS[d.primaryPartner] || this.PARTNER_PARAMS['streamglobal'];

                var baseContentRev = ds.lastContentRevenue * 1.05;
                contentRevenue = baseContentRev * platP.licMult * partP.revMult;

                if (d.platformCapex > 0 && platP.subsPerM > 0) {
                    subscribersGained = Math.round(d.platformCapex * platP.subsPerM);
                    platformRevenue = subscribersGained * 9.99 * 6 / 1000000;
                    ds.hasPlatform = true;
                    ds.platformCapexTotal += d.platformCapex;
                }

                var pb = this.PARTNERSHIP_BONUS[d.partnership];
                if (pb) {
                    if (pb.type === 'pct') {
                        partnershipBonus = contentRevenue * pb.value;
                    } else if (pb.type === 'flat') {
                        partnershipBonus = pb.value;
                    } else if (pb.type === 'variable') {
                        var seed = Math.round((ds.totalRevenue * 7 + ds.ipValue * 13) % 100);
                        var gamingFactor = seed > 35 ? 0.75 : 0.15;
                        partnershipBonus = (pb.high - pb.low) * gamingFactor + pb.low;
                    }
                }
                ds.partnershipType = d.partnership;

                var ipFromPartner = d.partnership === 'merchandise' ? 3.0 : d.partnership === 'gaming' ? 2.5 : d.partnership === 'live_events' ? 2.0 : 1.5;
                ipGain = (ds.numHits * 2.0) + ipFromPartner;

                catalogRevenue = catalogRevenue * (1 + ds.hitRate * 0.1);
                extraCosts = d.platformCapex;
                revenue = contentRevenue + platformRevenue + partnershipBonus + catalogRevenue + otherRevenue;
                costs = 45.0 + extraCosts;
                profit = revenue - costs;

                ds.lastContentRevenue = contentRevenue;

            } else if (period === 3) {
                var franchInvest = 45.0 * d.franchiseInvestPct / 100;
                var communityInvest = 45.0 * d.communityInvestPct / 100;

                var franchMult = ds.hitRate > 0.65 ? 2.8 : ds.hitRate > 0.50 ? 2.0 : ds.hitRate > 0.35 ? 1.5 : 1.0;
                franchiseRevenue = franchInvest * franchMult;

                var ancMult = this.ANCILLARY_MULT[d.ancillaryFocus] || 0.12;
                var ancBase = ds.ipValue > 0 ? ds.ipValue : 10;
                ancillaryRevenue = ancBase * ancMult;

                if (d.ancillaryFocus === 'gaming') {
                    var gamingSeed = Math.round((ds.totalRevenue * 11 + ds.ipValue * 17 + ds.cash * 3) % 100);
                    if (ds.ipValue > 25) {
                        ancillaryRevenue = ancBase * 0.22;
                    } else if (gamingSeed > 55) {
                        ancillaryRevenue = ancBase * 0.06;
                    }
                }

                var licP = this.LICENSING_PARAMS[d.licensingStrategy] || this.LICENSING_PARAMS['revenue_share'];
                var baseContentRev3 = ds.lastContentRevenue * 1.08;
                contentRevenue = baseContentRev3 * licP.revMult;

                if (ds.hasPlatform) {
                    var growthRate = 1.35 + (communityInvest / 45.0) * 0.5;
                    var totalSubs = ds.subscribers * growthRate + (ds.platformCapexTotal > 0 ? 5000 : 0);
                    subscribersGained = Math.round(totalSubs - ds.subscribers);
                    if (subscribersGained < 0) subscribersGained = 0;
                    platformRevenue = (ds.subscribers + subscribersGained) * 9.99 * 12 / 1000000;
                }

                var communityMult = 1 + (d.communityInvestPct * 0.025);
                ipGain = ((franchInvest * 0.5) + ancillaryRevenue * 0.3) * licP.ipMult * communityMult;

                catalogRevenue = catalogRevenue * (1 + ds.hitRate * 0.15);
                revenue = contentRevenue + franchiseRevenue + ancillaryRevenue + platformRevenue + catalogRevenue + otherRevenue;
                costs = 45.0;
                profit = revenue - costs;
            }

            ds.cash += profit;
            ds.totalRevenue += revenue;
            ds.totalProfit += profit;
            ds.ipValue += ipGain;
            ds.subscribers += subscribersGained;

            ds.revenueHistory.push(Math.round(revenue * 10) / 10);
            ds.profitHistory.push(Math.round(profit * 10) / 10);
            ds.ipValueHistory.push(Math.round(ds.ipValue * 10) / 10);

            /* EQIL score: the same 0 to 100 composite getPerformanceSummary builds (revenue 30, hit rate 25, IP value 20, profit 15, audience 10), computed from the rounded per-year histories of the play so far */
            var sRev = 0, sProf = 0, sk;
            for (sk = 0; sk < ds.revenueHistory.length; sk++) { sRev += ds.revenueHistory[sk] || 0; }
            for (sk = 0; sk < ds.profitHistory.length; sk++) { sProf += ds.profitHistory[sk] || 0; }
            var sIP = ds.ipValueHistory.length ? (ds.ipValueHistory[ds.ipValueHistory.length - 1] || 0) : 0;
            var sSubs = ds.subscribers || 0;
            var sHR = Math.round(ds.hitRate * 100) || 0;
            var sTotal = Math.round(Math.min(30, (sRev / 180) * 30) + Math.min(25, (sHR / 70) * 25) + Math.min(20, (sIP / 60) * 20) + Math.min(15, Math.max(0, (sProf / 55) * 15)) + Math.min(10, ((sSubs / 300000) + (sHR / 100)) * 5));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, sTotal || 0)) });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                revenue: Math.round(revenue * 10) / 10,
                costs: Math.round(costs * 10) / 10,
                profit: Math.round(profit * 10) / 10,
                ipValue: Math.round(ds.ipValue * 10) / 10,
                subscribers: ds.subscribers,
                hitRate: Math.round(ds.hitRate * 100),
                cash: Math.round(ds.cash * 10) / 10,
                contentRevenue: Math.round(contentRevenue * 10) / 10,
                ancillaryRevenue: Math.round(ancillaryRevenue * 10) / 10,
                platformRevenue: Math.round(platformRevenue * 10) / 10,
                franchiseRevenue: Math.round(franchiseRevenue * 10) / 10
            };
        }

