        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalRevenue = 0;
            var totalProfit = 0;
            var finalIPValue = 0;
            var finalSubs = 0;
            var hitRate = 0;

            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalRevenue += r.revenue || 0;
                totalProfit += r.profit || 0;
                finalIPValue = r.ipValue || 0;
                finalSubs = r.subscribers || 0;
                hitRate = r.hitRate || 0;
            }

            var revenueScore = Math.min(30, (totalRevenue / 180) * 30);
            var hitScore = Math.min(25, (hitRate / 70) * 25);
            var ipScore = Math.min(20, (finalIPValue / 60) * 20);
            var profitScore = Math.min(15, Math.max(0, (totalProfit / 55) * 15));
            var audienceScore = Math.min(10, ((finalSubs / 300000) + (hitRate / 100)) * 5);
            var totalScore = Math.round(revenueScore + hitScore + ipScore + profitScore + audienceScore);

            var performance = window.mySimulation.t('perf_developing_studio');
            if (totalScore >= 75) performance = window.mySimulation.t('perf_industry_leader');
            else if (totalScore >= 55) performance = window.mySimulation.t('perf_rising_powerhouse');
            else if (totalScore >= 35) performance = window.mySimulation.t('perf_competitive_player');

            var insights = [];
            if (totalRevenue > 180) insights.push(window.mySimulation.t('ins_revenue_target'));
            if (totalProfit > 40) insights.push(window.mySimulation.t('ins_profitability'));
            if (finalIPValue > 50) insights.push(window.mySimulation.t('ins_ip_portfolio'));
            if (finalSubs > 200000) insights.push(window.mySimulation.t('ins_subscribers'));
            if (hitRate > 65) insights.push(window.mySimulation.t('ins_hit_rate'));
            if (totalProfit < 0) insights.push(window.mySimulation.t('ins_losses'));
            if (finalIPValue < 15) insights.push(window.mySimulation.t('ins_low_ip'));
            if (insights.length === 0) insights.push(window.mySimulation.t('ins_solid_foundation'));

            return {
                totalRevenue: Math.round(totalRevenue * 10) / 10,
                totalProfit: Math.round(totalProfit * 10) / 10,
                finalIPValue: Math.round(finalIPValue * 10) / 10,
                subscribers: finalSubs,
                score: totalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (results.profit < 0) {
                return window.mySimulation.t('hint_loss');
            }
            if (period >= 2 && state.domainState.subscribers === 0 && state.domainState.hasPlatform === false) {
                return window.mySimulation.t('hint_no_platform');
            }
            if (period >= 2 && state.domainState.ipValue < 10) {
                return window.mySimulation.t('hint_low_ip');
            }
            if (results.profit > 15) {
                return window.mySimulation.t('hint_good_performance');
            }
            return null;
        }

