        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.textKey) : '';

            var ids = ['round1Controls', 'round2Controls', 'round3Controls'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el) el.style.display = 'none';
            }
            var activeEl = document.getElementById(round.controlsId);
            if (activeEl) activeEl.style.display = 'block';
        }

        _setupAllocListeners() {
            var inputIds = ['dramaAllocInput', 'realityAllocInput', 'docAnimAllocInput', 'filmAllocInput', 'spinoffAllocInput'];
            var totalEl = document.getElementById('allocTotalDisplay');

            function updateTotal() {
                var total = 0;
                for (var i = 0; i < inputIds.length; i++) {
                    var el = document.getElementById(inputIds[i]);
                    if (el) total += parseInt(el.value) || 0;
                }
                if (totalEl) {
                    totalEl.textContent = total + '%';
                    totalEl.style.color = total === 100 ? '#27ae60' : '#e74c3c';
                    totalEl.style.borderColor = total === 100 ? 'rgba(39,174,96,0.3)' : 'rgba(231,76,60,0.3)';
                    totalEl.style.background = total === 100 ? 'rgba(39,174,96,0.15)' : 'rgba(231,76,60,0.15)';
                }
            }

            for (var j = 0; j < inputIds.length; j++) {
                var el = document.getElementById(inputIds[j]);
                if (el) el.addEventListener('input', updateTotal);
            }
            updateTotal();
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ContentStudioAdapter(), {
            simulationType: 'contentstudio_media',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
